-- Phase 27 is additive. It intentionally does not alter the legacy Notification table
-- or its historical NotificationChannel enum.
CREATE TYPE "NotificationDeliveryChannel" AS ENUM ('IN_APP','EMAIL','SMS','WEB_PUSH','ANDROID_PUSH');
CREATE TYPE "NotificationPurpose" AS ENUM ('SECURITY','LEGAL','TRANSACTIONAL','OPERATIONAL','SERVICE_ANNOUNCEMENT','MARKETING');
CREATE TYPE "NotificationPriority" AS ENUM ('LOW','NORMAL','HIGH','URGENT');
CREATE TYPE "NotificationSensitivity" AS ENUM ('PUBLIC','ACCOUNT','FINANCIAL','SECURITY','RESTRICTED');
CREATE TYPE "NotificationCategoryStatus" AS ENUM ('ACTIVE','RETIRED');
CREATE TYPE "NotificationTemplateStatus" AS ENUM ('DRAFT','UNDER_REVIEW','APPROVED','PUBLISHED','RETIRED');
CREATE TYPE "NotificationRouteStatus" AS ENUM ('DRAFT','APPROVED','ACTIVE','RETIRED');
CREATE TYPE "NotificationMessageStatus" AS ENUM ('CREATED','FANOUT_COMPLETED','SUPERSEDED','EXPIRED');
CREATE TYPE "NotificationDeliveryStatus" AS ENUM ('PENDING','ELIGIBILITY_BLOCKED','QUEUED','SENDING','PROVIDER_ACCEPTED','DELIVERED','FAILED_RETRYABLE','FAILED_PERMANENT','BOUNCED','COMPLAINED','SUPPRESSED','CANCELLED','EXPIRED');
CREATE TYPE "NotificationAttemptStatus" AS ENUM ('STARTED','PROVIDER_ACCEPTED','FAILED');
CREATE TYPE "NotificationEndpointType" AS ENUM ('WEB_PUSH','ANDROID_PUSH');
CREATE TYPE "NotificationEndpointStatus" AS ENUM ('ACTIVE','STALE','INVALID','REVOKED','SUPPRESSED');
CREATE TYPE "NotificationPreferenceMode" AS ENUM ('ENABLED','DISABLED','MANDATORY','CONSENT_REQUIRED');
CREATE TYPE "NotificationDigestMode" AS ENUM ('IMMEDIATE','DAILY_DIGEST','DISABLED');
CREATE TYPE "NotificationConsentStatus" AS ENUM ('NOT_REQUESTED','REQUESTED','GRANTED','REVOKED','EXPIRED');
CREATE TYPE "NotificationSuppressionReason" AS ENUM ('HARD_BOUNCE','COMPLAINT','INVALID_PHONE','SMS_OPT_OUT','INVALID_PUSH_ENDPOINT','USER_REVOCATION','ADMIN_SECURITY_BLOCK','MARKETING_CONSENT_REVOKED','REPEATED_PERMANENT_FAILURE');
CREATE TYPE "NotificationReceiptType" AS ENUM ('ACCEPTED','DELIVERED','DEFERRED','BOUNCED','COMPLAINED','UNSUBSCRIBED','FAILED');
CREATE TYPE "NotificationFailureClass" AS ENUM ('TRANSIENT_NETWORK','PROVIDER_RATE_LIMIT','PROVIDER_UNAVAILABLE','INVALID_DESTINATION','AUTHENTICATION_FAILURE','CONFIGURATION_FAILURE','CONTENT_REJECTED','PERMISSION_DENIED','CONSENT_REQUIRED','SUPPRESSED_DESTINATION','EXPIRED_MESSAGE','UNKNOWN_PROVIDER_FAILURE');
CREATE TYPE "NotificationReconciliationReason" AS ENUM ('EVENT_ROUTE_NOT_CONFIGURED','RECIPIENT_NOT_RESOLVED','UNSAFE_CONTENT','PROVIDER_CONFIGURATION','DELIVERY_STALLED','RECEIPT_MISMATCH','ENDPOINT_INVALID');
CREATE TYPE "NotificationReconciliationStatus" AS ENUM ('OPEN','IN_PROGRESS','CONVERGED');

CREATE TABLE "NotificationCategory" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"key" TEXT UNIQUE NOT NULL,"purpose" "NotificationPurpose" NOT NULL,"defaultPriority" "NotificationPriority" NOT NULL DEFAULT 'NORMAL',"defaultSensitivity" "NotificationSensitivity" NOT NULL DEFAULT 'ACCOUNT',"mandatory" BOOLEAN NOT NULL DEFAULT false,"preferenceControlled" BOOLEAN NOT NULL DEFAULT true,"consentRequired" BOOLEAN NOT NULL DEFAULT false,"quietHoursBypass" BOOLEAN NOT NULL DEFAULT false,"digestEligible" BOOLEAN NOT NULL DEFAULT false,"retentionPolicyReference" TEXT,"status" "NotificationCategoryStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "NotificationTemplate" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"key" TEXT UNIQUE NOT NULL,"categoryKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "NotificationTemplateVersion" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"templateId" TEXT NOT NULL,"versionNumber" INTEGER NOT NULL,"status" "NotificationTemplateStatus" NOT NULL DEFAULT 'DRAFT',"locale" TEXT NOT NULL DEFAULT 'en-ZA',"purpose" "NotificationPurpose" NOT NULL,"sensitivity" "NotificationSensitivity" NOT NULL,"subjectTemplate" TEXT,"titleTemplate" TEXT,"plainTextTemplate" TEXT,"htmlTemplate" TEXT,"pushTemplate" TEXT,"smsTemplate" TEXT,"actionLabel" TEXT,"actionRoute" TEXT,"expiryMinutes" INTEGER,"publicationEvidence" JSONB,"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"publishedAt" TIMESTAMP(3),"retiredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("templateId","versionNumber"));
CREATE TABLE "NotificationTemplateVariable" ("id" TEXT PRIMARY KEY,"templateVersionId" TEXT NOT NULL,"name" TEXT NOT NULL,"type" TEXT NOT NULL,"required" BOOLEAN NOT NULL DEFAULT false,"maximumLength" INTEGER NOT NULL,"sensitivity" "NotificationSensitivity" NOT NULL DEFAULT 'ACCOUNT',"allowedChannels" "NotificationDeliveryChannel"[] NOT NULL,"escapingPolicy" TEXT NOT NULL DEFAULT 'ESCAPE',UNIQUE("templateVersionId","name"));
CREATE TABLE "NotificationEventRoute" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"key" TEXT UNIQUE NOT NULL,"sourceAuthority" TEXT NOT NULL,"sourceEventType" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("sourceAuthority","sourceEventType"));
CREATE TABLE "NotificationEventRouteVersion" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"routeId" TEXT NOT NULL,"versionNumber" INTEGER NOT NULL,"status" "NotificationRouteStatus" NOT NULL DEFAULT 'DRAFT',"categoryKey" TEXT NOT NULL,"recipientPolicyVersionId" TEXT NOT NULL,"templateKey" TEXT NOT NULL,"templateVersionId" TEXT NOT NULL,"channelPolicy" JSONB NOT NULL,"fallbackPolicy" TEXT NOT NULL,"priority" "NotificationPriority" NOT NULL DEFAULT 'NORMAL',"quietHoursBypass" BOOLEAN NOT NULL DEFAULT false,"digestMode" "NotificationDigestMode" NOT NULL DEFAULT 'IMMEDIATE',"expiryMinutes" INTEGER,"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"activatedAt" TIMESTAMP(3),"retiredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("routeId","versionNumber"));
CREATE TABLE "NotificationRecipientPolicyVersion" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"key" TEXT NOT NULL,"versionNumber" INTEGER NOT NULL,"status" "NotificationRouteStatus" NOT NULL DEFAULT 'DRAFT',"policy" JSONB NOT NULL,"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("key","versionNumber"));
CREATE TABLE "NotificationSourceReceipt" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"sourceAuthority" TEXT NOT NULL,"sourceEventId" TEXT NOT NULL,"sourceEventType" TEXT NOT NULL,"aggregateReference" TEXT NOT NULL,"payloadHash" TEXT NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL,"firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"status" TEXT NOT NULL,"routeVersionId" TEXT,"logicalMessageId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("sourceAuthority","sourceEventId"));
CREATE TABLE "NotificationMessage" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"dedupeKey" TEXT UNIQUE NOT NULL,"sourceReceiptId" TEXT NOT NULL,"recipientUserId" TEXT NOT NULL,"categoryKey" TEXT NOT NULL,"routeVersionId" TEXT NOT NULL,"templateVersionId" TEXT NOT NULL,"recipientPolicyVersionId" TEXT NOT NULL,"purpose" "NotificationPurpose" NOT NULL,"priority" "NotificationPriority" NOT NULL,"sensitivity" "NotificationSensitivity" NOT NULL,"renderVariablesHash" TEXT NOT NULL,"status" "NotificationMessageStatus" NOT NULL DEFAULT 'CREATED',"supersededByMessageId" TEXT,"expiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "NotificationRecipient" ("id" TEXT PRIMARY KEY,"messageId" TEXT NOT NULL,"subjectUserId" TEXT NOT NULL,"roleProjection" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("messageId","subjectUserId"));
CREATE TABLE "NotificationDelivery" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"messageId" TEXT NOT NULL,"recipientUserId" TEXT NOT NULL,"channel" "NotificationDeliveryChannel" NOT NULL,"endpointId" TEXT,"status" "NotificationDeliveryStatus" NOT NULL DEFAULT 'PENDING',"eligibilityReason" TEXT,"provider" TEXT,"providerMessageReference" TEXT,"renderedTitle" TEXT,"renderedBody" TEXT NOT NULL,"actionRoute" TEXT,"nextAttemptAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("messageId","channel"));
CREATE TABLE "NotificationDeliveryAttempt" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"deliveryId" TEXT NOT NULL,"attemptNumber" INTEGER NOT NULL,"operationId" TEXT UNIQUE NOT NULL,"provider" TEXT NOT NULL,"status" "NotificationAttemptStatus" NOT NULL DEFAULT 'STARTED',"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),"providerMessageReference" TEXT,"failureClass" "NotificationFailureClass","safeProviderCode" TEXT,"nextAttemptAt" TIMESTAMP(3),UNIQUE("deliveryId","attemptNumber"));
CREATE TABLE "NotificationProviderReceipt" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"provider" TEXT NOT NULL,"providerReceiptId" TEXT NOT NULL,"deliveryId" TEXT NOT NULL,"receiptType" "NotificationReceiptType" NOT NULL,"safePayload" JSONB,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("provider","providerReceiptId"));
CREATE TABLE "NotificationInboxItem" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"messageId" TEXT UNIQUE NOT NULL,"ownerUserId" TEXT NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"actionRoute" TEXT,"state" TEXT NOT NULL DEFAULT 'UNREAD',"readAt" TIMESTAMP(3),"archivedAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "NotificationPreference" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"categoryKey" TEXT NOT NULL,"channel" "NotificationDeliveryChannel" NOT NULL,"mode" "NotificationPreferenceMode" NOT NULL DEFAULT 'ENABLED',"digestMode" "NotificationDigestMode" NOT NULL DEFAULT 'IMMEDIATE',"timezone" TEXT,"quietHoursStart" TEXT,"quietHoursEnd" TEXT,"quietHoursDays" INTEGER[] NOT NULL DEFAULT ARRAY[]::INTEGER[],"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("userId","categoryKey","channel"));
CREATE TABLE "NotificationConsentRecord" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"userId" TEXT NOT NULL,"channel" "NotificationDeliveryChannel" NOT NULL,"purpose" "NotificationPurpose" NOT NULL DEFAULT 'MARKETING',"noticeVersion" TEXT NOT NULL,"status" "NotificationConsentStatus" NOT NULL DEFAULT 'NOT_REQUESTED',"source" TEXT NOT NULL,"grantedAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"requestEvidence" JSONB,"actorUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "NotificationEndpoint" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"ownerUserId" TEXT NOT NULL,"type" "NotificationEndpointType" NOT NULL,"provider" TEXT,"encryptedEndpoint" TEXT NOT NULL,"fingerprint" TEXT UNIQUE NOT NULL,"maskedDestination" TEXT NOT NULL,"deviceLabel" TEXT,"platform" TEXT,"applicationIdentifier" TEXT,"locale" TEXT,"timezone" TEXT,"status" "NotificationEndpointStatus" NOT NULL DEFAULT 'ACTIVE',"lastRefreshedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastSuccessfulDeliveryAt" TIMESTAMP(3),"lastFailureAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "NotificationSuppression" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"userId" TEXT,"endpointFingerprint" TEXT,"channel" "NotificationDeliveryChannel","purpose" "NotificationPurpose","reason" "NotificationSuppressionReason" NOT NULL,"evidence" JSONB,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reviewedAt" TIMESTAMP(3),"reviewedByUserId" TEXT);
CREATE TABLE "NotificationDigestBucket" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"userId" TEXT NOT NULL,"channel" "NotificationDeliveryChannel" NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"scheduledAt" TIMESTAMP(3) NOT NULL,"includedMessageIds" TEXT[] NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "NotificationAuditEvent" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"actorUserId" TEXT,"subjectUserId" TEXT,"eventType" TEXT NOT NULL,"entityReference" TEXT,"safeEvidence" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "NotificationReconciliationCase" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"sourceReceiptId" TEXT,"deliveryId" TEXT,"reason" "NotificationReconciliationReason" NOT NULL,"status" "NotificationReconciliationStatus" NOT NULL DEFAULT 'OPEN',"safeSummary" TEXT NOT NULL,"safeEvidence" JSONB,"openedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastObservedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"convergedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "NotificationEventIntent" ("id" TEXT PRIMARY KEY,"sourceAuthority" TEXT NOT NULL,"eventType" TEXT NOT NULL,"aggregateReference" TEXT NOT NULL,"operationId" TEXT UNIQUE NOT NULL,"safePayload" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "NotificationSecurePayload" ("id" TEXT PRIMARY KEY,"publicReference" TEXT UNIQUE NOT NULL,"eventIntentId" TEXT UNIQUE NOT NULL,"encryptedPayload" TEXT NOT NULL,"keyVersion" TEXT NOT NULL,"expiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX "NotificationDelivery_status_nextAttemptAt_idx" ON "NotificationDelivery"("status","nextAttemptAt");
CREATE INDEX "NotificationSourceReceipt_status_createdAt_idx" ON "NotificationSourceReceipt"("status","createdAt");
CREATE INDEX "NotificationInboxItem_ownerUserId_state_createdAt_idx" ON "NotificationInboxItem"("ownerUserId","state","createdAt");
CREATE INDEX "NotificationEndpoint_status_lastRefreshedAt_idx" ON "NotificationEndpoint"("status","lastRefreshedAt");
CREATE INDEX "NotificationReconciliationCase_status_createdAt_idx" ON "NotificationReconciliationCase"("status","createdAt");
CREATE INDEX "NotificationDigestBucket_status_scheduledAt_idx" ON "NotificationDigestBucket"("status","scheduledAt");
